export interface ConnectorConfig {
  asanaAccessToken: string
  asanaWorkspaceGid: string
  fetch?: typeof fetch
}

export interface JotformSubmission {
  id: string
  form_id: string
  title: string
  flat?: Record<string, string>
  answers?: Record<string, string>
}

export interface AsanaTaskResponse {
  gid: string
  name: string
  description: string
  resource_type: string
}

export interface HandleResult {
  taskId: string
  taskName: string
}

function getFieldValue(payload: JotformSubmission, fieldName: string): string | undefined {
  if (payload.flat && fieldName in payload.flat) {
    return payload.flat[fieldName]
  }
  if (payload.answers && fieldName in payload.answers) {
    return payload.answers[fieldName]
  }
  return undefined
}

function buildDescription(payload: JotformSubmission, usedFields: Set<string>): string {
  const allFields = { ...payload.flat, ...payload.answers }
  const lines: string[] = []
  for (const [key, value] of Object.entries(allFields)) {
    if (!usedFields.has(key) && value !== undefined && value !== '') {
      const label = key.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase())
      lines.push(`${label}: ${value}`)
    }
  }
  return lines.join('\n')
}

export async function handle(payload: JotformSubmission, config: ConnectorConfig): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.id) throw new Error('Missing required field: id')
  if (!payload.form_id) throw new Error('Missing required field: form_id')
  if (!payload.title) throw new Error('Missing required field: title')

  const firstName = getFieldValue(payload, 'first_name')
  const lastName = getFieldValue(payload, 'last_name')

  if (!firstName) throw new Error('Missing required field: first_name')
  if (!lastName) throw new Error('Missing required field: last_name')

  const taskName = `${firstName} ${lastName}`.trim()

  const usedFields = new Set(['first_name', 'last_name'])
  const description = buildDescription(payload, usedFields)

  const requestBody = {
    data: {
      name: taskName,
      description,
      workspace: config.asanaWorkspaceGid,
    },
  }

  const response = await fetchImpl('https://app.asana.com/api/1.0/tasks', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.asanaAccessToken}`,
      'Content-Type': 'application/json',
      'Accept': 'application/json',
    },
    body: JSON.stringify(requestBody),
  })

  if (!response.ok) {
    throw new Error(`Asana API error: ${response.status} ${response.statusText} for POST https://app.asana.com/api/1.0/tasks`)
  }

  const result = await response.json() as { data: AsanaTaskResponse }
  return {
    taskId: result.data.gid,
    taskName: result.data.name,
  }
}

